{
  "query": "select:WebSearch,WebFetch",
  "max_results": 5
}

{
  "query": "Hellinger 2011 Heating and cooling of protons in the fast solar wind between 0.3 and 1 AU Helios revisited temperature radial power law",
  "mode": "standard"
}

{
  "query": "Dakeyo 2022 ApJ statistical analysis radial evolution solar winds 0.1 1 au isopoly arXiv",
  "mode": "standard"
}

{
  "query": "Richardson 2018 Living Reviews Solar Physics solar wind stream interaction regions throughout the heliosphere",
  "mode": "standard"
}

{
  "url": "https://www.asu.cas.cz/~helinger/hellal11.pdf",
  "prompt": "Extract all fitted radial power-law exponents (density n_p, T_parallel, T_perp, total T_p, velocity, magnetic field) for the fast solar wind between 0.3 and 1 AU, with the speed selection used (e.g., v > 600 km/s), and the exact equation or table numbers/sections where they appear. Quote the numbers verbatim."
}

{
  "url": "https://www.asu.cas.cz/~helinger/hellal13.pdf",
  "prompt": "Extract all fitted radial power-law exponents (density, T_parallel, T_perp, total proton temperature, velocity, magnetic field) for slow and fast solar wind between 0.3 and 1 AU, with the speed bins used, and the exact equation, table, or section numbers. Quote numbers verbatim."
}

{
  "url": "https://arxiv.org/pdf/2207.03898",
  "prompt": "Extract quantitative results: the speed population classes (velocity at 1 AU), radial profiles of speed u(r) between 0.1 and 1 au (how much slow wind accelerates between 0.3 and 1 au, e.g., in km/s), fitted power-law exponents for density n ∝ r^-?, proton temperature T_p ∝ r^-? and electron temperature T_e ∝ r^-? for each speed class, polytropic indices, and table/figure numbers. Quote numbers verbatim."
}

{
  "command": "which pdftotext; mkdir -p /tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad/pdfs; ls /home/scabot/.claude/projects/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/tool-results/",
  "description": "Check pdftotext availability and list saved PDFs"
}

{
  "url": "http://space.asu.cas.cz/~helinger/hellal11.pdf",
  "prompt": "Extract all fitted radial power-law exponents (density n_p, T_parallel, T_perp, total T_p, velocity, magnetic field) for the fast solar wind between 0.3 and 1 AU, with the speed selection used, and the exact equation or table numbers/sections where they appear. Quote the numbers verbatim."
}

{
  "url": "http://space.asu.cas.cz/~helinger/hellal13.pdf",
  "prompt": "Extract all fitted radial power-law exponents (density, T_parallel, T_perp, total proton temperature, velocity, magnetic field) for slow and fast solar wind between 0.3 and 1 AU, with the speed bins used, and the exact equation, table, or section numbers. Quote numbers verbatim."
}

{
  "command": "python3 -c \"import pypdf; print(pypdf.__version__)\" 2>&1; python3 -c \"import fitz; print(fitz.__doc__)\" 2>&1; python3 -c \"import pdfminer; print(pdfminer.__version__)\" 2>&1; which mutool qpdf gs 2>&1",
  "description": "Check for Python PDF text extraction libraries"
}

{
  "command": "S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad; grep -n -i -E \"R\\s*[-−–]|power|exponent|\\\\\\\\propto|∝|fit\" $S/txt/hellinger2011.txt | head -80",
  "description": "Search Hellinger 2011 text for power-law fits"
}

{
  "command": "S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad; sed -n 140,320p $S/txt/hellinger2011.txt",
  "description": "Read Hellinger 2011 data and results section"
